import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path.cwd()))


def check():
    from checkout import checkout
    from pricing import make_quote

    cents = 1250
    quote = make_quote(cents)
    if quote != cents and quote != {"total": cents}:
        raise RuntimeError("Unexpected quote precondition")
    try:
        result = checkout(cents)
    except TypeError as exc:
        if str(exc) != "'int' object is not subscriptable":
            raise
        return "reproduced", "checkout(1250) raises TypeError instead of returning 1250", 1
    if result != cents:
        return "reproduced", f"checkout(1250) returned {result!r} instead of 1250", 1
    return "passed", "checkout(1250) returns 1250", 0


try:
    outcome, reason, code = check()
except Exception as exc:
    outcome, reason, code = "error", f"{type(exc).__name__}: {exc}", 2

print("NEIN_PROBE_RESULT " + json.dumps({"check": "checkout-quote-contract", "outcome": outcome, "reason": reason}))
sys.exit(code)
